"""Check the authored blind-junction candidate before Native construction.

The map and geometry checks are CPU preparation. Native actor placement,
camera visibility, and physical signal behavior require later source review.
"""

import hashlib
import json
import math
from pathlib import Path
from xml.etree import ElementTree as ET

from shapely.geometry import LineString, Polygon


def _point(value):
    if (not isinstance(value, list) or len(value) != 2 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in value)):
        raise ValueError("Finite XY point required")
    return value


def validate(candidate_path):
    candidate_path = Path(candidate_path)
    candidate = json.loads(candidate_path.read_text())
    if candidate.get("format") != "c24811-blind-site-candidate-v1":
        raise ValueError("C24811 site candidate required")
    binding = candidate["map"]
    if set(binding) != {"path", "sha256"} or Path(binding["path"]).name != binding["path"]:
        raise ValueError("Local hashed map binding required")
    map_path = candidate_path.parent / binding["path"]
    if hashlib.sha256(map_path.read_bytes()).hexdigest() != binding["sha256"]:
        raise ValueError("Authored map changed")
    root = ET.parse(map_path).getroot()
    if root.tag != "OpenDRIVE":
        raise ValueError("OpenDRIVE map required")
    junction_id = candidate["junction_id"]
    if root.find(f"junction[@id='{junction_id}']") is None:
        raise ValueError("Authored junction missing")
    crossing = Polygon([_point(p) for p in candidate["intersection_polygon_xy_m"]])
    if not crossing.is_valid or crossing.area <= 0:
        raise ValueError("Finite intersection geometry required")
    roads = {int(r.get("id")): r for r in root.findall("road")}
    entrances = candidate["entrances"]
    if set(entrances) != {"ego", "other"}:
        raise ValueError("Two governed entrances required")
    ids = []
    for name, entry in entrances.items():
        road = roads.get(entry["road_id"])
        if road is None:
            raise ValueError("Approach road missing")
        signals = [s for s in road.findall("signals/signal")
                   if s.get("id") == str(entry["map_signal_id"]) and
                   s.find("validity") is not None and
                   int(s.find("validity").get("fromLane")) <= entry["lane_id"] <=
                   int(s.find("validity").get("toLane"))]
        if len(signals) != 1:
            raise ValueError("Governed signal missing or ambiguous: " + name)
        marks = [o for o in road.findall("objects/object")
                 if o.get("id") == str(entry["stop_line_object_id"]) and
                 o.get("name") == "StopLine"]
        if len(marks) != 1:
            raise ValueError("Marked stop line missing: " + name)
        _point(entry["viewpoint_xy_m"])
        _point(entry["target_vehicle_xy_m"])
        if entry["viewpoint_xy_m"] == entry["target_vehicle_xy_m"]:
            raise ValueError("Zero sight ray")
        ids.append(entry["map_signal_id"])
    if len(set(ids)) != 2:
        raise ValueError("Distinct signal IDs required")
    footprint = Polygon([_point(p) for p in candidate["occluder"]["planned_footprint_xy_m"]])
    if not footprint.is_valid or footprint.area <= 0:
        raise ValueError("Valid occluder footprint required")
    clearance = candidate["occluder"]["minimum_corridor_clearance_m"]
    if type(clearance) not in (int, float) or clearance < 1:
        raise ValueError("Positive engineering clearance required")
    hits = {}
    for name, entry in entrances.items():
        ray = LineString([entry["viewpoint_xy_m"], entry["target_vehicle_xy_m"]])
        hits[name] = ray.intersects(footprint)
        if not hits[name]:
            raise ValueError("Planned occluder misses sight ray: " + name)
        corridor = LineString([_point(p) for p in entry["vehicle_corridor_centerline_xy_m"]])
        if footprint.distance(corridor) < clearance:
            raise ValueError("Planned occluder intrudes on vehicle corridor: " + name)
    return {"map_sha256": binding["sha256"], "junction_id": junction_id,
            "planned_sight_ray_intersections": hits,
            "planned_corridor_clearance_m": {name: round(footprint.distance(
                LineString(entry["vehicle_corridor_centerline_xy_m"])), 3)
                for name, entry in entrances.items()},
            "native_visibility_verified": False, "physical_acceptance": False}


if __name__ == "__main__":
    print(json.dumps(validate(Path(__file__).with_name("blind-site-candidate.json")), indent=2))

"""Reversible Native Off-state request for every inventoried entrance.

Off readback is an engineering setup check. Physical complete inoperability of
installed, uncovered vehicular heads still requires original source review.
"""

from contextlib import contextmanager


def find_entrance_lights(world, entrance_road_lanes):
    lights = list(world.get_actors().filter("traffic.traffic_light*"))
    selected = []
    for road_id, lane_id in entrance_road_lanes:
        matching = [light for light in lights if any(
            waypoint.road_id == road_id and waypoint.lane_id == lane_id
            for waypoint in light.get_affected_lane_waypoints())]
        if len(matching) != 1:
            raise ValueError("Expected one governing Native light per entrance")
        selected.append(matching[0])
    if len(selected) < 2 or len({light.id for light in selected}) != len(selected):
        raise ValueError("Distinct inventoried entrance heads required")
    return selected


@contextmanager
def request_all_off(world, lights, traffic_light_state):
    with request_all_state(world, lights, traffic_light_state.Off) as selected:
        yield selected


@contextmanager
def request_all_state(world, lights, desired_state):
    if len(lights) < 2:
        raise ValueError("All entrance lights required")
    if desired_state is None:
        raise ValueError("Explicit Native signal state required")
    original = []
    try:
        for light in lights:
            frozen = light.is_frozen() if callable(getattr(light, "is_frozen", None)) else False
            original.append((light, light.get_state(), frozen))
            light.freeze(True)
            light.set_state(desired_state)
        world.tick()
        if any(light.get_state() != desired_state for light in lights):
            raise ValueError("Native signal-state readback failed")
        yield lights
    finally:
        for light, state, frozen in reversed(original):
            light.set_state(state)
            light.freeze(frozen)
        if original:
            world.tick()
            if any(light.get_state() != state or
                   (callable(getattr(light, "is_frozen", None)) and light.is_frozen() != frozen)
                   for light, state, frozen in original):
                raise ValueError("Native signal restoration readback failed")

"""Spawn and measure a Native occluder candidate at a map-bound placement.

Planar ray intersection is a CPU geometry check, not proof of camera visibility.
"""

from contextlib import ExitStack, contextmanager
import math

from shapely.geometry import LineString, MultiPoint


def _xy(point):
    x, y = float(point.x), float(point.y)
    if not math.isfinite(x) or not math.isfinite(y):
        raise ValueError("Nonfinite ray or occluder position")
    return x, y


@contextmanager
def spawn_verified_occluder(world, blueprint, transform, approach_rays,
                            vehicle_corridors=None, minimum_clearance_m=0):
    """Check realized sight obstruction and clearance from both travel paths."""
    if not isinstance(approach_rays, dict) or set(approach_rays) != {"ego", "other"}:
        raise ValueError("Two approach rays required")
    actor = world.try_spawn_actor(blueprint, transform)
    if actor is None:
        raise ValueError("Native occluder spawn failed")
    try:
        vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
        if len(vertices) < 4:
            raise ValueError("Native occluder body vertices missing")
        footprint = MultiPoint([_xy(point) for point in vertices]).convex_hull
        if footprint.area <= 0:
            raise ValueError("Native occluder footprint has no area")
        hits = {}
        for name, pair in approach_rays.items():
            if not isinstance(pair, (tuple, list)) or len(pair) != 2:
                raise ValueError("Invalid approach ray: " + name)
            ray = LineString([_xy(point) for point in pair])
            if ray.length <= 0:
                raise ValueError("Zero approach ray: " + name)
            hits[name] = ray.intersects(footprint)
        if not all(hits.values()):
            raise ValueError("Spawned geometry does not obstruct both approach rays")
        clearances = {}
        if vehicle_corridors is not None:
            if (set(vehicle_corridors) != {"ego", "other"} or
                    not math.isfinite(minimum_clearance_m) or minimum_clearance_m < 1):
                raise ValueError("Two corridors and positive engineering clearance required")
            for name, points in vehicle_corridors.items():
                if len(points) < 2:
                    raise ValueError("Vehicle corridor requires two points")
                corridor = LineString([_xy(point) for point in points])
                clearances[name] = footprint.distance(corridor)
                if clearances[name] < minimum_clearance_m:
                    raise ValueError("Spawned occluder intrudes on vehicle corridor: " + name)
        yield {"actor": actor, "footprint_xy_m": list(footprint.exterior.coords),
               "approach_ray_intersections": hits,
               "vehicle_corridor_clearance_m": clearances}
    finally:
        actor.destroy()


@contextmanager
def spawn_matching_occluder(world, blueprints, transform, approach_rays,
                            vehicle_corridors, minimum_clearance_m):
    """Choose the first realized Native footprint meeting the authored geometry.

    Rejected actors are destroyed by spawn_verified_occluder. The selected
    blueprint and realized footprint remain in the original junction context.
    """
    candidates = sorted(blueprints, key=lambda blueprint: blueprint.id)
    if not candidates:
        raise ValueError("No Native occluder blueprint candidates")
    rejected = []
    with ExitStack() as stack:
        for blueprint in candidates:
            try:
                realized = stack.enter_context(spawn_verified_occluder(
                    world, blueprint, transform, approach_rays,
                    vehicle_corridors, minimum_clearance_m))
            except ValueError as error:
                rejected.append({"blueprint_id":blueprint.id,"reason":str(error)})
                continue
            realized["blueprint_id"] = blueprint.id
            realized["rejected_candidates"] = rejected
            yield realized
            return
    raise ValueError("No Native occluder footprint met both rays and corridor clearance")

"""Four original Native RGB source streams with exact frame joins.

No synthetic media substitutes for a missing camera frame. The caller must
seal actual capture and assess pixels before any physical claim.
"""

import json
import math
import subprocess
from contextlib import contextmanager
from pathlib import Path
from queue import Empty


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def validate_plan(path):
    path = Path(path)
    plan = json.loads(path.read_text())
    if plan.get("format") != "c24811-four-camera-native-capture-plan-v1" or plan.get("rate_hz") != 20:
        raise ValueError("Pinned four-camera source plan required")
    if type(plan.get("duration_s")) is not int or not 5 <= plan["duration_s"] <= 120:
        raise ValueError("Bounded Native capture duration required")
    site = json.loads(path.with_name("blind-site-candidate.json").read_text())
    if plan.get("map_sha256") != site["map"]["sha256"]:
        raise ValueError("Camera plan map differs from site")
    cameras = plan.get("cameras")
    if not isinstance(cameras, list) or tuple(row.get("name") for row in cameras) != CAMERAS:
        raise ValueError("Four named original source cameras required")
    for row in cameras:
        if (row.get("width"), row.get("height")) != SIZES[row["name"]]:
            raise ValueError("Source camera dimensions differ from pinned profile")
        pose = row.get("pose")
        if (not isinstance(pose, dict) or set(pose) != {"x", "y", "z", "yaw", "pitch"} or
                any(type(v) not in (int, float) or not math.isfinite(v) for v in pose.values()) or
                type(row.get("fov_deg")) not in (int, float) or not 20 <= row["fov_deg"] <= 120 or
                not row.get("pose_strategy")):
            raise ValueError("Finite source camera pose, FOV and strategy required")
    required = {"trace.jsonl", "vehicle_signal_history.jsonl", "video_frames.jsonl",
                "junction_context.json", "capture/evidence.jsonl"}
    if set(plan.get("raw_sources", [])) != required:
        raise ValueError("Complete raw source inventory required")
    return {"names": list(CAMERAS), "rate_hz": 20,
            "frames_planned": plan["duration_s"]*20,
            "native_pixels_verified": False}


def source_camera_frame(queue, expected_frame):
    if type(expected_frame) is not int or expected_frame < 0:
        raise ValueError("Nonnegative Native frame required")
    for _ in range(8):
        try:
            image = queue.get(timeout=10)
        except Empty as error:
            raise ValueError("Source camera frame missing") from error
        if image.frame == expected_frame:
            return bytes(image.raw_data)
        if image.frame > expected_frame:
            raise ValueError("Source camera skipped Native frame")
    raise ValueError("Source camera frame join failed")


@contextmanager
def source_cameras(world, ego, carla, plan):
    sensors = {}
    try:
        for row in plan["cameras"]:
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            for key, value in (("image_size_x", row["width"]),
                               ("image_size_y", row["height"]),
                               ("fov", row["fov_deg"]), ("sensor_tick", 0.05)):
                blueprint.set_attribute(key, str(value))
            pose = row["pose"]
            transform = carla.Transform(
                carla.Location(x=pose["x"], y=pose["y"], z=pose["z"]),
                carla.Rotation(yaw=pose["yaw"], pitch=pose["pitch"]))
            kwargs = {"attach_to": ego} if row["name"] == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transform, **kwargs)
            if sensor is None:
                raise ValueError("Native source camera spawn failed: " + row["name"])
            sensors[row["name"]] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()


@contextmanager
def ffv1_writer(path, size):
    path = Path(path)
    width, height = size
    if path.exists() or type(width) is not int or type(height) is not int or width <= 0 or height <= 0:
        raise ValueError("Fresh finite-size source video required")
    process = subprocess.Popen([
        "ffmpeg", "-hide_banner", "-loglevel", "error", "-n", "-f", "rawvideo",
        "-pixel_format", "bgra", "-video_size", f"{width}x{height}",
        "-framerate", "20", "-i", "pipe:0", "-an", "-c:v", "ffv1",
        "-level", "3", "-pix_fmt", "bgr0", str(path)],
        stdin=subprocess.PIPE, stderr=subprocess.PIPE)
    count = 0
    def write(data):
        nonlocal count
        if len(data) != width*height*4 or process.poll() is not None:
            raise ValueError("Source-camera BGRA size or encoder mismatch")
        process.stdin.write(data)
        count += 1
    try:
        yield write
    finally:
        process.stdin.close()
        code = process.wait(timeout=60)
        stderr = process.stderr.read().decode(errors="replace")
        process.stderr.close()
        if code or count == 0:
            raise ValueError("Native FFV1 encoder failed: " + stderr[-500:])


if __name__ == "__main__":
    print(json.dumps(validate_plan(Path(__file__).with_name("capture-plan.json")), indent=2))

"""Build frame-aligned Native source rows for three distinct complete bodies.

This recorder reads Native feedback. It does not infer legal priority, physical
signal inoperability, or camera visibility from an authored configuration.
"""

import math


ROLES = ("ego", "earlier", "occupant")


def _finite(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("Finite " + label + " required")
    return float(value)


def signed_front_distance(vertices, point, upstream_normal):
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError("Complete Native body vertices required")
    px, py = (_finite(value, "stop-line point") for value in point)
    nx, ny = (_finite(value, "upstream normal") for value in upstream_normal)
    if abs(math.hypot(nx, ny)-1) > 1e-5:
        raise ValueError("Unit upstream normal required")
    return min(((_finite(vertex[0], "body x")-px)*nx +
                (_finite(vertex[1], "body y")-py)*ny) for vertex in vertices)


def actor_row(actor, route, junction_id):
    transform = actor.get_transform()
    vertices = actor.bounding_box.get_world_vertices(transform)
    if len(vertices) < 4:
        raise ValueError("Complete Native body required")
    xy = [[_finite(v.x, "body x"), _finite(v.y, "body y")] for v in vertices]
    velocity = actor.get_velocity()
    speed = math.sqrt(sum(_finite(getattr(velocity, axis), "velocity")**2 for axis in "xyz"))
    return {"intersection_id": junction_id, "speed_mps": speed,
            "front_to_stop_line_signed_m": signed_front_distance(
                xy, route["stop_line_point_xy_m"], route["upstream_normal_xy"]),
            "body_vertices_xy_m": xy}


def source_row(frame, time_s, junction_id, lights, actors, routes):
    if type(frame) is not int or frame < 0:
        raise ValueError("Nonnegative Native frame required")
    _finite(time_s, "Native time")
    if type(junction_id) is not int or junction_id <= 0:
        raise ValueError("Authored junction ID required")
    if set(actors) != set(ROLES) or set(routes) != set(ROLES):
        raise ValueError("Three distinct Native actors and routes required")
    if len({actors[role].id for role in ROLES}) != 3:
        raise ValueError("Distinct observed Native vehicle IDs required")
    if len(lights) != 2 or len({light.id for light in lights}) != 2:
        raise ValueError("Two distinct observed Native heads required")
    states = {str(light.id): str(light.get_state()).split(".")[-1] for light in lights}
    if any(state not in ("Off", "Green", "Yellow", "Red") for state in states.values()):
        raise ValueError("Unsupported observed Native head state")
    row = {"frame": frame, "time_s": float(time_s), "signal_states": states,
           "actor_ids": {role: actors[role].id for role in ROLES}}
    for role in ROLES:
        row[role] = actor_row(actors[role], routes[role], junction_id)
    return row

"""Original-frame observations for inoperative and operative signal cases.

Native Off, actual installed/uncovered status, and timing are retained separately;
this reports no legal conclusion about cautious proceeding or yielding.
"""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


REQUIRED = ("junction_context.json", "vehicle_signal_history.jsonl", "video_frames.jsonl")
STOP_LINE_TOLERANCE_M = 0.5


def _number(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite " + label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _body(actor):
    vertices = actor.get("body_vertices_xy_m")
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError("Missing complete vehicle body")
    points = []
    for vertex in vertices:
        if not isinstance(vertex, list) or len(vertex) != 2:
            raise ValueError("Invalid body vertex")
        points.append((_number(vertex[0], "body x"), _number(vertex[1], "body y")))
    return MultiPoint(points).convex_hull


def analyze(root: Path, expected_signal_state="Off"):
    root = Path(root)
    if expected_signal_state not in ("Off", "Green", "Yellow", "Red"):
        raise ValueError("Explicit governing signal state required")
    hashes = {}
    for name in REQUIRED:
        path = root/name
        if not path.is_file():
            raise ValueError("Missing required original source: " + name)
        hashes[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    ctx = json.loads((root/"junction_context.json").read_text())
    for key in ("native_map_id", "intersection_id", "signal_head_video_source",
                "all_entrances_source", "stop_line_source", "occluder_geometry_source",
                "sight_ray_source"):
        if not ctx.get(key):
            raise ValueError("Missing sourced junction context: " + key)
    if ctx.get("stop_line_exists") is not True:
        raise ValueError("Selected stop-line branch lacks marked line")
    heads = ctx.get("signal_heads")
    if not isinstance(heads, list) or len(heads) < 2:
        raise ValueError("All governing signal heads required")
    ids = []
    for head in heads:
        if not head.get("native_id") or not head.get("entrance_id") or head.get("installed") is not True or head.get("uncovered") is not True:
            raise ValueError("Installed uncovered head identity missing")
        ids.append(head["native_id"])
    if len(set(ids)) != len(ids):
        raise ValueError("Duplicate governing signal head")
    polygon = Polygon(ctx.get("intersection_polygon_xy_m", []))
    if not polygon.is_valid or polygon.area <= 0:
        raise ValueError("Invalid intersection polygon")
    history, frames = _rows(root/"vehicle_signal_history.jsonl"), _rows(root/"video_frames.jsonl")
    if len(history) < 4 or len(history) != len(frames):
        raise ValueError("Incomplete three-vehicle history")
    samples, previous = [], (-1, -math.inf)
    first_stop = {role: None for role in ("ego", "earlier", "occupant")}
    first_entry = {role: None for role in first_stop}
    for i, (row, frame) in enumerate(zip(history, frames)):
        fid, time = row.get("frame"), _number(row.get("time_s"), "time")
        if type(fid) is not int or fid <= previous[0] or time <= previous[1]:
            raise ValueError("Nonmonotone original history")
        previous = fid, time
        if frame.get("video_frame") != i or frame.get("carla_frame") != fid or frame.get("time_s") != time:
            raise ValueError("Original frame join failed")
        states = row.get("signal_states")
        if not isinstance(states, dict) or set(states) != {str(v) for v in ids} or any(v != expected_signal_state for v in states.values()):
            raise ValueError("All governing heads must be observed " + expected_signal_state + " at every original frame")
        sample = {"frame": fid, "time_s": time,
                  "governing_signal_state": expected_signal_state,
                  "all_heads_off": expected_signal_state == "Off"}
        for role in first_stop:
            actor = row.get(role)
            if not isinstance(actor, dict) or actor.get("intersection_id") != ctx["intersection_id"]:
                raise ValueError("Participant junction mismatch: " + role)
            speed = _number(actor.get("speed_mps"), "speed")
